orchestrator.

=item * C<< $msg->compute_engine() >> / C<< $msg->compute_engine($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeEngineOrchestrator>)

Optional. If set, indicates that the cluster should use Compute Engine as
the orchestrator.

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmOrchestrator

When set in
[Orchestrator][google.cloud.hypercomputecluster.v1beta.Orchestrator],
indicates that the cluster should use [Slurm](https://slurm.schedmd.com/) as
the orchestrator.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->login_nodes() >> / C<< $msg->login_nodes($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmLoginNodes>)

Required. Configuration for login nodes, which allow users to access the
cluster over SSH.

=item * C<< $msg->node_sets() >> / C<< $msg->node_sets($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmNodeSet>)

Optional. Compute resource configuration for the Slurm nodesets in your
cluster. If not specified, the cluster won't create any nodes.

=item * C<< $msg->partitions() >> / C<< $msg->partitions($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmPartition>)

Optional. Configuration for the Slurm partitions in your cluster. Each
partition can contain one or more nodesets, and you can submit separate
jobs on each partition. If you don't specify at least one partition in your
cluster, you can't submit jobs to the cluster.

=item * C<< $msg->default_partition() >> / C<< $msg->default_partition($value) >>

Type: C<String>

Optional. Default partition to use for submitted jobs that do not
explicitly specify a partition. Required if and only if there is more than
one partition, in which case it must match the id of one of the partitions.

=item * C<< $msg->prolog_bash_scripts() >> / C<< $msg->prolog_bash_scripts($value) >>

Type: C<String>

Optional. Slurm [prolog
scripts](https://slurm.schedmd.com/prolog_epilog.html), which will be
executed by compute nodes before a node begins running a new job. Values
must not be empty.

=item * C<< $msg->epilog_bash_scripts() >> / C<< $msg->epilog_bash_scripts($value) >>

Type: C<String>

Optional. Slurm [epilog
scripts](https://slurm.schedmd.com/prolog_epilog.html), which will be
executed by compute nodes whenever a node finishes running a job. Values
must not be empty.

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmNodeSet

Configuration for Slurm nodesets in the cluster. Nodesets are groups of
compute nodes used by Slurm that are responsible for running workloads
submitted to the cluster.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->compute_instance() >> / C<< $msg->compute_instance($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeInstanceSlurmNodeSet>)

Optional. If set, indicates that the nodeset should be backed by Compute
Engine instances.

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Required. The ID for the nodeset, which allows it to be referenced by
cluster partitions. The nodeset ID must start with a lowercase letter
(`a`-`z`), use only lowercase letters or numbers, and contain up to 15
characters. For example, specify `nodeset001`.

=item * C<< $msg->compute_id() >> / C<< $msg->compute_id($value) >>

Type: C<String>

Required. The ID of the compute resource on which this nodeset runs. Must
match a key in the cluster's
[compute_resources][google.cloud.hypercomputecluster.v1beta.Cluster.compute_resources].

=item * C<< $msg->storage_configs() >> / C<< $msg->storage_configs($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::StorageConfig>)

Optional. How [storage
resources][google.cloud.hypercomputecluster.v1beta.StorageResource] should
be mounted on each compute node.

=item * C<< $msg->static_node_count() >> / C<< $msg->static_node_count($value) >>

Type: C<Int64>

Optional. Number of nodes to be statically created for this nodeset. The
cluster will attempt to ensure that at least this many nodes exist at all
times.

=item * C<< $msg->max_dynamic_node_count() >> / C<< $msg->max_dynamic_node_count($value) >>

Type: C<Int64>

Optional. Controls how many additional nodes a cluster can bring online to
handle workloads. Set this value to enable dynamic node creation and limit
the number of additional nodes the cluster can bring online. Leave empty if
you do not want the cluster to create nodes dynamically, and instead rely
only on static nodes.

=item * C<< $msg->resource_policy_config() >> / C<< $msg->resource_policy_config($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ResourcePolicyConfig>)

Optional. Resource policy configuration for the nodeset.

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeInstanceSlurmNodeSet

When set in a
[SlurmNodeSet][google.cloud.hypercomputecluster.v1beta.SlurmNodeSet],
indicates that the nodeset should be backed by Compute Engine VM instances.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->startup_script() >> / C<< $msg->startup_script($value) >>

Type: C<String>

Optional. [Startup
script](https://cloud.google.com/compute/docs/instances/startup-scripts/linux)
to be run on each VM instance in the nodeset. Max 256KB.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeInstanceSlurmNodeSet::LabelsEntry>)

Optional.
[Labels](https://cloud.google.com/compute/docs/labeling-resources) that
should be applied to each VM instance in the nodeset.

=item * C<< $msg->boot_disk() >> / C<< $msg->boot_disk($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::BootDisk>)

Optional. Boot disk for the compute instance

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ResourcePolicyConfig

Policy describing how VM instances should be created.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->accelerator_topology() >> / C<< $msg->accelerator_topology($value) >>

Type: C<String>

Optional. Specifies the topology required to create a partition for VMs
that have interconnected accelerators, in the format `AxB` or `AxBxC`,
where `A`, `B`, and `C` are integers.

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmPartition

Configuration for Slurm partitions in the cluster. Partitions are groups of
nodesets, and are how clients specify where their workloads should be run.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->id() >> / C<< $msg->id($value) >>

Type: C<String>

Required. ID of the partition, which is how users will identify it. Must
conform to [RFC-1034](https://datatracker.ietf.org/doc/html/rfc1034)
(lower-case, alphanumeric, and at most 63 characters).

=item * C<< $msg->node_set_ids() >> / C<< $msg->node_set_ids($value) >>

Type: C<String>

Required. IDs of the nodesets that make up this partition. Values must
match
[SlurmNodeSet.id][google.cloud.hypercomputecluster.v1beta.SlurmNodeSet.id].

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmLoginNodes

Configuration for Slurm [login
nodes](https://slurm.schedmd.com/quickstart_admin.html#login) in the cluster.
Login nodes are Compute Engine VM instances that allow users to access the
cluster over SSH.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->count() >> / C<< $msg->count($value) >>

Type: C<Int64>

Required. Number of login node instances to create.

=item * C<< $msg->zone() >> / C<< $msg->zone($value) >>

Type: C<String>

Required. Name of the zone in which login nodes should run, e.g.,
`us-central1-a`. Must be in the same region as the cluster, and must match
the zone of any other resources specified in the cluster.

=item * C<< $msg->machine_type() >> / C<< $msg->machine_type($value) >>

Type: C<String>

Required. Name of the Compute Engine [machine
type](https://cloud.google.com/compute/docs/machine-resource) to use for
login nodes, e.g. `n2-standard-2`.

=item * C<< $msg->startup_script() >> / C<< $msg->startup_script($value) >>

Type: C<String>

Optional. [Startup
script](https://cloud.google.com/compute/docs/instances/startup-scripts/linux)
to be run on each login node instance. Max 256KB.
The script must complete within the system-defined default timeout of 5
minutes. For tasks that require more time, consider running them in the
background using methods such as `&` or `nohup`.

=item * C<< $msg->enable_os_login() >> / C<< $msg->enable_os_login($value) >>

Type: C<Bool>

Optional. Whether [OS Login](https://cloud.google.com/compute/docs/oslogin)
should be enabled on login node instances.

=item * C<< $msg->enable_public_ips() >> / C<< $msg->enable_public_ips($value) >>

Type: C<Bool>

Optional. Whether login node instances should be assigned [external IP
addresses](https://cloud.google.com/compute/docs/ip-addresses#externaladdresses).

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmLoginNodes::LabelsEntry>)

Optional.
[Labels](https://cloud.google.com/compute/docs/labeling-resources) that
should be applied to each login node instance.

=item * C<< $msg->storage_configs() >> / C<< $msg->storage_configs($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::StorageConfig>)

Optional. How [storage
resources][google.cloud.hypercomputecluster.v1beta.StorageResource] should
be mounted on each login node.

=item * C<< $msg->instances() >> / C<< $msg->instances($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeInstance>)

Output only. Information about the login node instances that were created
in Compute Engine.

=item * C<< $msg->boot_disk() >> / C<< $msg->boot_disk($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::BootDisk>)

Optional. Boot disk for the login node.

=item * C<< $msg->network_tags() >> / C<< $msg->network_tags($value) >>

Type: C<String>

Optional. Network tags to be applied to each login node instance.
A maximum of 64 network tags are allowed.

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ServiceAccount

Service account email and scopes

Inherits from L<Protobuf::Message>.

=head3 Accessors

