=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::Node

A resource representing a compute node managed by Cluster Director.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. [Relative resource name](https://google.aip.dev/122) of the
node, in the format
`projects/{project}/locations/{location}/clusters/{cluster}/nodes/{node}`.

=item * C<< $msg->zone() >> / C<< $msg->zone($value) >>

Type: C<String>

Output only. Name of the zone in which the node is running, e.g.
`us-central1-a`.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Hypercomputecluster::V1beta::Node::State>)

Output only. High-level lifecycle state of the node.

=item * C<< $msg->state_message() >> / C<< $msg->state_message($value) >>

Type: C<String>

Output only. Human-readable message providing extra information about the
current state.

=item * C<< $msg->running_jobs() >> / C<< $msg->running_jobs($value) >>

Type: C<Bool>

Output only. Indicates whether the node is currently executing workloads.

=item * C<< $msg->accepting_jobs() >> / C<< $msg->accepting_jobs($value) >>

Type: C<Bool>

Output only. Indicates whether the node is available for new job
allocations.

=item * C<< $msg->provisioning_model() >> / C<< $msg->provisioning_model($value) >>

Type: C<Enum> (L<Google::Cloud::Hypercomputecluster::V1beta::Node::ProvisioningModel>)

Output only. Provisioning model of the node.

=item * C<< $msg->slurm_details() >> / C<< $msg->slurm_details($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmNodeDetails>)

Output only. Slurm-specific details for the node.

=item * C<< $msg->compute_engine_details() >> / C<< $msg->compute_engine_details($value) >>

Type: C<Message> (L<Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::ComputeEngineNodeDetails>)

Output only. Compute Engine-specific details for the node.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time that the node was originally created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time that the node was most recently updated.

=back

=head3 Enum: Node::State

=over 4

=item * C<STATE_UNSPECIFIED> => C<0>

=item * C<CREATING> => C<1>

=item * C<ACTIVE> => C<2>

=item * C<SUSPENDING> => C<3>

=item * C<SUSPENDED> => C<4>

=item * C<REPAIRING> => C<5>

=item * C<FAILED> => C<6>

=item * C<DELETING> => C<7>

=item * C<UNPROVISIONED> => C<8>

=back

=head3 Enum: Node::ProvisioningModel

=over 4

=item * C<PROVISIONING_MODEL_UNSPECIFIED> => C<0>

=item * C<ON_DEMAND> => C<1>

=item * C<SPOT> => C<2>

=item * C<RESERVATION_BOUND> => C<3>

=item * C<FLEX_START> => C<4>

=back

=head2 Google::Cloud::Hypercomputecluster::V1beta::HypercomputeCluster::SlurmNodeDetails

Slurm-specific details for a Node.

Inherits from L<Protobuf::Message>.

=head3 Accessors

